// Private exact original Q8 vocabulary R1 geometry screen. Root executes GPU.
#include "flash/FlashAffine.hpp"
#include "flash/FlashGreedyGPU.hpp"
#include "metal/abi/FlashAffine.h"
#include "FlashHeadQ8R1V8HostProvenance.hpp"
#include "engine/Json.hpp"
#import <Foundation/Foundation.h>
#include <algorithm>
#include <array>
#include <bit>
#include <cmath>
#include <cstdlib>
#include <cstring>
#include <filesystem>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <limits>
#include <span>
#include <sstream>
#include <stdexcept>
