namespace {
using namespace splash::flash;
using namespace splash::metal;
constexpr uint32_t N=248320,K=2560,Sticky=0x40000000;
constexpr uint16_t Sentinel=0x7fc1;
void require(bool b,const std::string &m){if(!b)throw std::runtime_error(m);}
float number(uint16_t w){return std::bit_cast<float>(uint32_t(w)<<16);}
uint16_t bf16(float v){uint32_t u=std::bit_cast<uint32_t>(v);if((u&0x7f800000u)==0x7f800000u)return uint16_t((u>>16)|((u&0x7fffffu)?64u:0));return uint16_t((u+0x7fff+((u>>16)&1u))>>16);}
uint64_t randomWord(uint64_t x){x+=0x9e3779b97f4a7c15ull;x=(x^(x>>30))*0xbf58476d1ce4e5b9ull;x=(x^(x>>27))*0x94d049bb133111ebull;return x^(x>>31);}
struct Variant{uint32_t c,sg;bool shuffle;std::string name()const{return "flash_head_q8_r1_v8_c"+std::to_string(c)+"_s"+std::to_string(sg)+(shuffle?"_shuffle":"_byte");}};
std::vector<Variant> variants(){std::vector<Variant> out;for(auto [c,sg]:std::array<std::pair<uint32_t,uint32_t>,11>{{{1,4},{1,8},{2,2},{2,4},{2,8},{4,2},{4,4},{4,8},{8,2},{8,4},{8,8}}})for(bool sh:{false,true})out.push_back({c,sg,sh});return out;}
std::vector<uint32_t> choices(){const char *v=std::getenv("FLASH_HEAD_Q8_R1_VARIANTS");std::vector<uint32_t> out;if(!v){for(uint32_t i=0;i<22;i++)out.push_back(i);return out;}std::stringstream in(v);std::string s;while(std::getline(in,s,',')){size_t used=0;const auto value=std::stoul(s,&used);require(used==s.size()&&value<22,"invalid variant selector");out.push_back(uint32_t(value));}require(!out.empty(),"empty variants");return out;}
uint32_t integer(const char *name,uint32_t fallback,uint32_t max){const char *raw=std::getenv(name);if(!raw)return fallback;size_t used=0;const auto v=std::stoul(raw,&used);require(used==std::strlen(raw)&&v&&v<=max,std::string("invalid ")+name);return uint32_t(v);}
struct Guard{MetalBuffer base,view;uint32_t n;Guard(MetalBackend &b,uint32_t count):n(count){base=b.allocateBuffer(uint64_t(n+64)*2,BufferStorage::Shared,"private Q8 R1 guarded logits");view=b.view(base,64,uint64_t(n)*2);clear();}void clear(){std::fill_n(static_cast<uint16_t *>(base.contents()),n+64,Sentinel);}void check()const{const auto *p=static_cast<const uint16_t *>(base.contents());for(uint32_t i=0;i<32;i++)require(p[i]==Sentinel&&p[n+32+i]==Sentinel,"logit guards overwritten");}std::span<const uint16_t> values()const{return {static_cast<const uint16_t *>(view.contents()),n};}};
struct Times{std::vector<double> gpu,wall;void add(CommandTiming t){gpu.push_back(t.gpuSeconds);wall.push_back(t.wallSeconds);}static double median(std::vector<double> v){std::sort(v.begin(),v.end());return v.size()%2?v[v.size()/2]:(v[v.size()/2-1]+v[v.size()/2])*.5;}void write(std::ostream &o)const{o<<"{\"repeats\":"<<gpu.size()<<",\"median_gpu_seconds\":"<<median(gpu)<<",\"median_wall_seconds\":"<<median(wall)<<",\"gpu_seconds\":[";for(size_t i=0;i<gpu.size();i++){if(i)o<<',';o<<gpu[i];}o<<"]}";}};
struct Error{uint64_t mismatch=0,nonfinite=0;double se=0,sr=0,maxabs=0;void add(uint16_t a,uint16_t b){mismatch+=a!=b;const float av=number(a),bv=number(b);if(!std::isfinite(av)||!std::isfinite(bv)){nonfinite++;return;}const double d=double(av)-bv;se+=d*d;sr+=double(bv)*bv;maxabs=std::max(maxabs,std::abs(d));}double l2()const{return std::sqrt(se/std::max(1e-30,sr));}void write(std::ostream &o)const{o<<"{\"bf16_mismatches\":"<<mismatch<<",\"nonfinite\":"<<nonfinite<<",\"relative_l2\":"<<l2()<<",\"max_abs\":"<<maxabs<<'}';}};
FlashAffineParams params(const FlashAffineProjection &p){return {1,1,p.inputSize,p.outputSize,1,8,64,0,p.weightRowStrideBytes,p.weightExpertStrideBytes,p.parameterRowStrideBytes,p.parameterExpertStrideBytes};}
void candidate(CommandGraph &g,const FlashAffineProjection &p,MetalBuffer x,MetalBuffer y,MetalBuffer d,Variant v){require(p.experts==1&&p.bits==8&&p.groupSize==64&&p.inputSize==K&&p.outputSize&&p.outputSize<=N,"invalid private Q8 geometry");require(x.sizeBytes()>=K*2&&y.sizeBytes()>=uint64_t(p.outputSize)*2&&d.sizeBytes()>=4,"short private buffers");require(!x.sameView(y)&&!d.sameView(y),"private alias rejected");g.add(v.name(),{x,p.weights->buffer,p.scales->buffer,p.biases->buffer,x,y,d},params(p),{(p.outputSize+v.c*v.sg-1)/(v.c*v.sg),1,1},{v.sg*32,1,1});}
std::vector<uint16_t> inputs(uint32_t pattern){std::vector<uint16_t> x(K);double sum=0;for(uint32_t k=0;k<K;k++){float f=0;if(pattern==0)f=float(int(randomWord(k+0x18827)%2047)-1023)/512.f;else if(pattern==1)f=(k&1)?-1.25f:1.25f;else if(pattern==2)f=(k%64<32)?32.f:-32.f;else if(pattern==3)f=(k%32==0)?1.f:0.f;else f=(k==0)?std::numeric_limits<float>::infinity():.5f;x[k]=bf16(f);sum+=double(number(x[k]))*number(x[k]);}if(pattern==0){const float inv=float(std::sqrt(K/sum));for(auto &v:x)v=bf16(number(v)*inv);}return x;}
void cpu(){uint64_t checks=0;require(sizeof(CommandTiming)==200,"ABI200 required");for(uint32_t k=0;k<K;k++){const uint32_t g=k/64,lane=k%32,sub=(k%64)/32;require(g*64+sub*32+lane==k,"lane K address changed");for(uint32_t q=0;q<256;q++){const uint32_t shift=(lane&3u)*8;const uint32_t packed=q<<shift;require(((packed>>shift)&255u)==q,"word unpack changed code");checks++;}}for(auto v:variants())for(uint32_t n:{1u,17u,N}){std::vector<uint32_t> hits(n);const uint32_t count=(n+v.c*v.sg-1)/(v.c*v.sg);for(uint32_t group=0;group<count;group++)for(uint32_t sg=0;sg<v.sg;sg++)for(uint32_t c=0;c<v.c;c++){uint32_t col=group*v.c*v.sg+sg*v.c+c;if(col<n)hits[col]++;}for(auto h:hits){require(h==1,"column coverage changed");checks++;}}for(uint32_t q:{0u,1u,127u,128u,254u,255u})for(float scale:{-.00390625f,.0078125f,1.f,-14.25f})for(float bias:{-128.f,-.0009765625f,128.f}){const float a=float(q)*scale+bias;const float b=float(q)*scale+bias;require(std::bit_cast<uint32_t>(a)==std::bit_cast<uint32_t>(b),"affine coefficient changed");checks++;}std::cout<<"{\"pass\":true,\"cpu_checks\":"<<checks<<",\"gpu_commands\":0,\"command_timing_bytes\":"<<sizeof(CommandTiming)<<",\"host_object_provenance\":"<<kFlashOracleHostObjectProvenance<<"}\n";}
}
int main(int argc,char **argv){@autoreleasepool{try{
if(argc==2&&std::string(argv[1])=="--cpu-self-test"){cpu();return 0;}require(argc==4,"usage: ORACLE METALLIB PACKAGE REPORT_JSON | --cpu-self-test");require(!std::filesystem::exists(argv[3]),"use fresh report filename");const auto all=variants();const auto selected=choices();const uint32_t repeats=integer("FLASH_HEAD_Q8_R1_REPEATS",5,20);const uint32_t outputN=integer("FLASH_HEAD_Q8_R1_OUTPUTS",N,N);const uint32_t patterns=integer("FLASH_HEAD_Q8_R1_PATTERNS",4,5);MetalBackend backend(argv[1]);auto weights=FlashWeights::load(backend,argv[2]);auto p=weights.projection("language_model.lm_head");require(p.inputSize==K&&p.outputSize==N&&p.bits==8&&p.groupSize==64,"wrong source vocabulary");p.outputSize=outputN;auto x=backend.allocateBuffer(K*2,BufferStorage::Shared,"private Q8 R1 input");auto d0=backend.allocateBuffer(4,BufferStorage::Shared,"private Q8 control diagnostics");auto d1=backend.allocateBuffer(4,BufferStorage::Shared,"private Q8 candidate diagnostics");Guard control(backend,outputN),output(backend,outputN);auto greedy=allocateGreedyGPUWorkspace(backend,1,outputN);auto r0=backend.allocateBuffer(16,BufferStorage::Shared,"private Q8 control greedy"),r1=backend.allocateBuffer(16,BufferStorage::Shared,"private Q8 candidate greedy");std::ofstream report(argv[3]);require(bool(report),"cannot write report");report<<std::setprecision(12)<<"{\"schema\":\"flash-private-original-q8-r1-geometry-v8-screen-v1\",\"source_identity\":"<<splash::json::quote(weights.sourceIdentity())<<",\"manifest_fingerprint\":"<<splash::json::quote(weights.manifestFingerprint())<<",\"host_object_provenance\":"<<kFlashOracleHostObjectProvenance<<",\"numerical_policy\":\"original-f32-affine-coefficient-lane-k-order-simd32-sum-bf16-output-v1\",\"extra_operand_bytes\":0,\"projection_outputs\":"<<outputN<<",\"full_vocabulary\":"<<(outputN==N?"true":"false")<<",\"cases\":[";bool first=true,valid=true;uint64_t commands=0;
for(uint32_t pattern=0;pattern<patterns;pattern++){auto host=inputs(pattern);const char *inputPath=std::getenv("FLASH_HEAD_Q8_R1_INPUT_BF16");if(inputPath&&pattern==0){std::ifstream in(inputPath,std::ios::binary|std::ios::ate);require(in&&in.tellg()==K*2,"real BF16 input must contain exact 2560 words");in.seekg(0);in.read(reinterpret_cast<char *>(host.data()),K*2);require(bool(in),"cannot read real input");}std::memcpy(x.contents(),host.data(),K*2);CommandGraph raw;addAffine(raw,x,p,control.view,d0,1);CommandGraph canonical;addAffine(canonical,x,p,control.view,d0,1);addGreedyGPU(canonical,control.view,greedy,r0,1,outputN);*static_cast<uint32_t *>(d0.contents())=Sticky;(void)backend.submitCommand(canonical.dispatches());commands++;control.check();const std::vector<uint16_t> reference(control.values().begin(),control.values().end());const auto greedyReference=*static_cast<const FlashGreedyGPURowResult *>(r0.contents());const uint32_t diagnosticReference=*static_cast<const uint32_t *>(d0.contents());
for(uint32_t index:selected){const auto v=all[index];output.clear();*static_cast<uint32_t *>(d1.contents())=Sticky;CommandGraph projection;candidate(projection,p,x,output.view,d1,v);CommandGraph graph;candidate(graph,p,x,output.view,d1,v);addGreedyGPU(graph,output.view,greedy,r1,1,outputN);(void)backend.submitCommand(graph.dispatches());commands++;Times cand,base,projCand,projBase;for(uint32_t sample=0;sample<repeats;sample++){if(sample%2==0){base.add(backend.submitCommand(canonical.dispatches()));cand.add(backend.submitCommand(graph.dispatches()));projBase.add(backend.submitCommand(raw.dispatches()));projCand.add(backend.submitCommand(projection.dispatches()));}else{cand.add(backend.submitCommand(graph.dispatches()));base.add(backend.submitCommand(canonical.dispatches()));projCand.add(backend.submitCommand(projection.dispatches()));projBase.add(backend.submitCommand(raw.dispatches()));}commands+=4;}output.check();control.check();Error error;for(uint32_t n=0;n<outputN;n++)error.add(output.values()[n],reference[n]);const auto result=*static_cast<const FlashGreedyGPURowResult *>(r1.contents());const bool greedyExact=std::memcmp(&result,&greedyReference,16)==0;const bool diagExact=*static_cast<const uint32_t *>(d1.contents())==diagnosticReference;bool pass=!error.mismatch&&greedyExact&&diagExact;valid&=pass;if(!first)report<<',';first=false;report<<"{\"pattern\":"<<pattern<<",\"input_kind\":"<<splash::json::quote(inputPath&&pattern==0?"real-normalized-head-bf16":"synthetic")<<",\"variant_index\":"<<index<<",\"kernel\":"<<splash::json::quote(v.name())<<",\"columns_per_simd\":"<<v.c<<",\"simd_groups\":"<<v.sg<<",\"shuffle_words\":"<<(v.shuffle?"true":"false")<<",\"error\":";error.write(report);report<<",\"greedy_exact\":"<<(greedyExact?"true":"false")<<",\"diagnostics_exact\":"<<(diagExact?"true":"false")<<",\"control_greedy\":"<<greedyReference.token<<",\"candidate_greedy\":"<<result.token<<",\"complete_control_timing\":";base.write(report);report<<",\"complete_candidate_timing\":";cand.write(report);report<<",\"projection_control_timing\":";projBase.write(report);report<<",\"projection_candidate_timing\":";projCand.write(report);report<<",\"pass\":"<<(pass?"true":"false")<<'}';report.flush();}
}report<<"],\"gpu_commands\":"<<commands<<",\"valid\":"<<(valid?"true":"false")<<"}\n";return valid?0:2;
}catch(const std::exception &e){std::cerr<<"private Q8 R1 oracle: "<<e.what()<<'\n';return 1;}}}
